static constexpr int BONE_USED_BY_HITBOX = 0x00000100;
static constexpr int BONE_USED_BY_ATTACHMENT = 0x00000200;
static constexpr int BONE_USED_BY_VERTEX_LOD0 = 0x00000400;
static constexpr int BONE_USED_BY_VERTEX_MASK = 0x0003FC00;
static constexpr int BONE_USED_BY_BONE_MERGE = 0x00040000;
// Marker for `boneref` ONLY - never a boneflag, so it cannot reach the .mdl.
// Deliberately outside the BONE_* range so it can never be confused for one.
static constexpr int kBoneRefProceduralKeep = 0x40000000;
static constexpr int STUDIO_LOOPING = 0x0001;
static constexpr int STUDIO_DELTA = 0x0004;
static constexpr int STUDIO_POST = 0x0010;
static constexpr int STUDIO_HIDDEN = 0x0400;
static constexpr int STUDIO_NOFORCELOOP = 0x8000;
static constexpr int STUDIOHDR_FLAGS_AUTOGENERATED_HITBOX = 1 << 0;
static constexpr int STUDIOHDR_FLAGS_FORCE_OPAQUE = 1 << 2;
static constexpr int STUDIOHDR_FLAGS_TRANSLUCENT_TWOPASS = 1 << 3;
static constexpr int STUDIOHDR_FLAGS_STATIC_PROP = 1 << 4;
static constexpr int STUDIOHDR_FLAGS_HASSHADOWLOD = 1 << 6;
static constexpr int STUDIOHDR_FLAGS_USE_SHADOWLOD_MATERIALS = 1 << 8;
static constexpr int STUDIOHDR_FLAGS_FORCE_PHONEME_CROSSFADE = 1 << 12;
static constexpr int STUDIOHDR_FLAGS_AMBIENT_BOOST = 1 << 16;
static constexpr int STUDIOHDR_FLAGS_DO_NOT_CAST_SHADOWS = 1 << 17;
// StudioBoneFlexComponent_t (format/mdl.h)
static constexpr int STUDIO_BONE_FLEX_TX = 0;
static constexpr int STUDIO_BONE_FLEX_TZ = 2;

static constexpr double kPiD = 3.14159265358979323846;
static constexpr float kMaxCoord = 16384.0f;  // MAX_COORD_INTEGER

